diff --git a/mail/themes/shared/mail/msgSelectOffline.css b/mail/themes/shared/mail/msgSelectOffline.css
index 1d3558d4e50..fcfcd9ce69a 100644
--- a/mail/themes/shared/mail/msgSelectOffline.css
+++ b/mail/themes/shared/mail/msgSelectOffline.css
@@ -39,6 +39,7 @@ treechildren::-moz-tree-image(syncCol) {
 }

 treechildren::-moz-tree-image(syncCol, synchronize-true) {
+  fill: currentColor !important;
   fill-opacity: 1;
 }

diff --git a/mail/themes/shared/mail/preferences/preferences.css b/mail/themes/shared/mail/preferences/preferences.css
index 7c37ea2745f..c1c162536af 100644
--- a/mail/themes/shared/mail/preferences/preferences.css
+++ b/mail/themes/shared/mail/preferences/preferences.css
@@ -418,6 +418,16 @@ checkbox {
   margin-inline: 0;
 }

+treechildren::-moz-tree-row(selected) {
+  background-color: var(--in-content-item-selected) !important;
+  border-color: transparent;
+  outline-color: transparent;
+}
+
+treechildren::-moz-tree-cell-text(selected) {
+  color: var(--in-content-item-selected-text);
+}
+
 .align-no-label {
   margin-inline-start: 4px;
 }
@@ -699,6 +709,12 @@ checkbox {
   border-radius: unset;
 }

+#synchronizeTree treechildren::-moz-tree-twisty(selected, focus),
+#synchronizeTree treechildren::-moz-tree-image(folderNameCol, selected, focus) {
+  fill: color-mix(in srgb, currentColor 20%, transparent) !important;
+  stroke: currentColor !important;
+}
+
